from mk import *
from lib import fbd
STRICT["on"] = True
import math
G = 6.67e-11; M = 5.98e24; R = 6.37e6; GM = G * M
r1 = R + 7.2e5; r2 = R + 4.1e5
a1 = GM / r1 ** 2; v2 = math.sqrt(GM / r2); T2 = 2 * math.pi * r2 / v2 / 3600
Ed = GM * 300 / (2 * 6.9e6)
TF = ["נכון", "שגוי", "אי אפשר לקבוע"]

def fig():
    g = Fig(420, 290, "כדור הארץ ושני מסלולים מעגליים של הלוויין: בשלב הראשון בגובה 720 קילומטר, ובשלב השני בגובה 410 קילומטר")
    cx, cy = 210, 150
    g.circle(cx, cy, 90, fill="var(--d-fill)", stroke="var(--d-line)"); g.heb(cx, cy + 6, "כדור הארץ")
    g.circle(cx, cy, 108, fill="none", stroke="var(--d-line)", width=1.2, dash="4 4")
    g.circle(cx, cy, 130, fill="none", stroke="var(--d-line)", width=1.2, dash="7 4")
    g.ball(cx - 76, cy - 76, r=5); g.heb(cx - 100, cy - 112, "שלב 1"); g.text(cx - 100, cy - 96, "720 km")
    g.ball(cx + 76, cy - 76, r=5); g.heb(cx + 62, cy - 52, "שלב 2"); g.text(cx + 62, cy - 36, "410 km")
    return g

E(id="bagrut-2018-q6", year=2018, label="2018 שאלה 6", topic="gravitation", sub="grav-energy", diff=3, fig=fig,
  stem=r"באוגוסט 2017 שיגרו סוכנות החלל הישראלית וסוכנות החלל הצרפתית לוויין זעיר בשם VENµS, לתצפית ולמחקר. בלוויין יש טכנולוגיות מתקדמות, וחלקן פותחו בישראל, ובהן שני מנועי סילון חדשים שנבדקים בחלל לראשונה. הלוויין אמור להיות בחלל בערך שלוש וחצי שנים: בשלב הראשון בגובה $720\,\text{km}$ מעל פני כדור הארץ, ובשלב השני בגובה $410\,\text{km}$. המסלול מעגלי, ומתחשבים רק בהשפעה של כדור הארץ. נתונים: מסת כדור הארץ $5.98 \times 10^{24}\,\text{kg}$, רדיוס כדור הארץ $6.37 \times 10^6\,\text{m}$.",
  parts=[
    P("א", r"מה תאוצת הנפילה החופשית של הלוויין בשלב הראשון (גודל וכיוון)?", num(a1, "m/s^2", tol=1), ["principle", "algebra"], [
        S(r"רדיוס המסלול", r"מודדים מהמרכז: הרדיוס ועוד הגובה", r"r_1 = 6.37 \times 10^6 + 7.2 \times 10^5 = 7.09 \times 10^6\,\text{m}"),
        S(r"תאוצת הכבידה", r"מכוונת אל מרכז כדור הארץ", r"g^* = \frac{GM}{r_1^2} = \frac{6.67 \times 10^{-11} \cdot 5.98 \times 10^{24}}{(7.09 \times 10^6)^2} \approx 7.9\,\text{m/s}^2", eq=r"g^* = \frac{GM}{r^2}"),
    ], r"$\approx 7.9\,\text{m/s}^2$, אל מרכז כדור הארץ", key=r"g*=7.9 m/s²"),
    P("ב1", r"מה המהירות של הלוויין במסלול של השלב השני?", num(v2, "m/s", tol=1), ["principle", "algebra"], [
        S(r"רדיוס המסלול", r"הרדיוס ועוד הגובה של השלב השני", r"r_2 = 6.37 \times 10^6 + 4.1 \times 10^5 = 6.78 \times 10^6\,\text{m}"),
        S(r"משוואת כוחות בכיוון המרכז", r"כוח הכבידה נותן את התאוצה אל המרכז. המסה של הלוויין מצטמצמת", r"\frac{GMm}{r_2^2} = m\frac{v^2}{r_2} \;\Rightarrow\; v = \sqrt{\frac{GM}{r_2}} = \sqrt{\frac{3.99 \times 10^{14}}{6.78 \times 10^6}} \approx 7.67 \times 10^3\,\text{m/s}", eq=r"F = \frac{GMm}{r^2},\qquad a_R = \frac{v^2}{r}"),
    ], r"$v \approx 7670\,\text{m/s}$", key=r"v=7661 m/s"),
    P("ב2", r"מה זמן המחזור, בשעות, של הלוויין בשלב השני?", num(T2, "h", tol=1), ["algebra", "units"], [
        S(r"היקף חלקי מהירות", r"גודל המהירות קבוע", r"T = \frac{2\pi r_2}{v} = \frac{2\pi \cdot 6.78 \times 10^6}{7670} \approx 5.55 \times 10^3\,\text{s}", eq=r"v = \frac{2\pi r}{T}"),
        S(r"בשעות", r"בשעה שלושת אלפים ושש מאות שניות", r"T \approx \frac{5550}{3600} \approx 1.54\,\text{h}"),
    ], r"$T \approx 1.54\,\text{h}$", key=r"T=1.547 hr"),
    P("ג1", r"האם ההיגד נכון, לא נכון, או שאי אפשר לקבוע: האנרגיה הפוטנציאלית של הלוויין בשלב הראשון גדולה מזו שבשלב השני? נמקו.", choice(TF, 0), ["principle", "signs"], [
        S(r"האנרגיה הפוטנציאלית", r"היא שלילית, ומתקרבת לאפס ככל שהרדיוס גדל. בשלב הראשון הרדיוס גדול יותר", r"U = -\frac{GMm}{r},\qquad r_1 > r_2 \;\Rightarrow\; U_1 > U_2", eq=r"U = -\frac{GMm}{r}"),
    ], r"נכון"),
    P("ג2", r"האם ההיגד נכון, לא נכון, או שאי אפשר לקבוע: האנרגיה הקינטית של הלוויין בשלב הראשון גדולה מזו שבשלב השני? נמקו.", choice(TF, 1), ["principle"], [
        S(r"המהירות במסלול", r"ממשוואת הכוחות, האנרגיה הקינטית הפוכה לרדיוס. ככל שהרדיוס קטן, המהירות גדלה", r"E_k = \frac{GMm}{2r},\qquad r_1 > r_2 \;\Rightarrow\; E_{k1} < E_{k2}"),
    ], r"לא נכון", key=r"wrong"),
    P("ג3", r"האם ההיגד נכון, לא נכון, או שאי אפשר לקבוע: האנרגיה הכוללת של הלוויין בשלב הראשון שווה לזו שבשלב השני? נמקו.", choice(TF, 1), ["principle", "signs"], [
        S(r"האנרגיה הכוללת במסלול", r"היא תלויה ברדיוס. ברדיוס גדול היא פחות שלילית, כלומר גדולה יותר", r"E = -\frac{GMm}{2r},\qquad r_1 > r_2 \;\Rightarrow\; E_1 > E_2"),
    ], r"לא נכון: האנרגיה הכוללת בשלב הראשון גדולה יותר", key=r"not correct"),
    P("ד", r"הסעיף הזה עוסק בלוויין דמיוני. לוויין שמסתו $300\,\text{kg}$ נע סביב כדור הארץ במסלול מעגלי ברדיוס $6900\,\text{km}$. מה תוספת האנרגיה המזערית שצריך כדי שהלוויין ישתחרר מהמשיכה של כדור הארץ?", num(Ed, "J", tol=1), ["principle", "algebra"], [
        S(r"האנרגיה הכוללת במסלול", r"האנרגיה הקינטית היא חצי מגודל האנרגיה הפוטנציאלית", r"E = \frac{GMm}{2r} - \frac{GMm}{r} = -\frac{GMm}{2r}", eq=r"U = -\frac{GMm}{r}"),
        S(r"להגיע לאנרגיה אפס", r"באנרגיה המזערית הלוויין מגיע לאינסוף בלי מהירות", r"\Delta E = 0 - E = \frac{GMm}{2r} = \frac{3.99 \times 10^{14} \cdot 300}{2 \cdot 6.9 \times 10^6} \approx 8.67 \times 10^9\,\text{J}"),
    ], r"$\approx 8.7 \times 10^9\,\text{J}$"),
  ],
  concepts=["תאוצת הכבידה בגובה", "מהירות במסלול", "אנרגיה במסלול", "אנרגיית מילוט"],
  summary=r"הלוויין VENµS בשני גבהים: התאוצה, המהירות וזמן המחזור, והשוואה בין האנרגיות בשני המסלולים.",
  review="הנחה שלי.\nמה לבדוק: רק לאשר.")
